-- ---------------------------------------------------------------------------------------------
-- What the Prisma schema cannot say (written by hand; keep in step with docs/staff.md).
-- ---------------------------------------------------------------------------------------------

-- One open shift per employee, one open break per shift: two clock-in requests racing each other
-- (two tabs, a double tap, a retry) cannot both succeed. The API maps the violation to "already
-- clocked in".
CREATE UNIQUE INDEX "attendance_sessions_one_open_per_employee" ON "attendance_sessions" ("employee_id") WHERE "clock_out_at" IS NULL;
CREATE UNIQUE INDEX "break_sessions_one_open_per_session" ON "break_sessions" ("session_id") WHERE "end_at" IS NULL;

-- At most one usable invitation per employee: sending a new one revokes the old one first.
CREATE UNIQUE INDEX "employee_invitations_one_live_per_employee" ON "employee_invitations" ("employee_id") WHERE "accepted_at" IS NULL AND "revoked_at" IS NULL;

-- One live pay period per date range (overlaps are refused by the API under an advisory lock).
CREATE UNIQUE INDEX "payroll_periods_one_live_range" ON "payroll_periods" ("workspace_id", "start_date", "end_date") WHERE "status" NOT IN ('cancelled', 'reversed');

-- The same transaction reference can't be recorded twice for an employee and method.
CREATE UNIQUE INDEX "payroll_payments_one_reference" ON "payroll_payments" ("workspace_id", "employee_id", "method", "reference") WHERE "reference" IS NOT NULL AND "status" = 'completed';

CREATE INDEX "attendance_sessions_open" ON "attendance_sessions" ("workspace_id") WHERE "clock_out_at" IS NULL;

ALTER TABLE "attendance_sessions" ADD CONSTRAINT "attendance_sessions_times" CHECK ("clock_out_at" IS NULL OR "clock_out_at" >= "clock_in_at");
ALTER TABLE "attendance_sessions" ADD CONSTRAINT "attendance_sessions_approval" CHECK ("approval_status" IN ('pending', 'approved', 'rejected'));
ALTER TABLE "break_sessions" ADD CONSTRAINT "break_sessions_times" CHECK ("end_at" IS NULL OR "end_at" >= "start_at");
ALTER TABLE "break_sessions" ADD CONSTRAINT "break_sessions_kind" CHECK ("kind" IN ('rest', 'meal'));
ALTER TABLE "shift_schedules" ADD CONSTRAINT "shift_schedules_times" CHECK ("ends_at" > "starts_at");
ALTER TABLE "employees" ADD CONSTRAINT "employees_status" CHECK ("status" IN ('active', 'on_leave', 'inactive'));
ALTER TABLE "employees" ADD CONSTRAINT "employees_employment_type" CHECK ("employment_type" IN ('full_time', 'part_time', 'casual', 'contract'));
ALTER TABLE "pay_rate_history" ADD CONSTRAINT "pay_rate_history_rate" CHECK ("hourly_rate" >= 0);
ALTER TABLE "overtime_policies" ADD CONSTRAINT "overtime_policies_multipliers" CHECK ("multiplier" >= 1 AND "holiday_multiplier" >= 1 AND ("double_time_multiplier" IS NULL OR "double_time_multiplier" >= 1));
ALTER TABLE "payroll_periods" ADD CONSTRAINT "payroll_periods_dates" CHECK ("start_date" <= "end_date");
ALTER TABLE "payroll_periods" ADD CONSTRAINT "payroll_periods_status" CHECK ("status" IN ('draft', 'pending_approval', 'approved', 'partially_paid', 'paid', 'cancelled', 'correction_required', 'payment_failed', 'reversed'));
ALTER TABLE "payroll_items" ADD CONSTRAINT "payroll_items_paid" CHECK ("paid_minor" >= 0);
ALTER TABLE "payroll_adjustments" ADD CONSTRAINT "payroll_adjustments_amount" CHECK ("amount_minor" > 0 AND "kind" IN ('earning', 'deduction'));
ALTER TABLE "payroll_payments" ADD CONSTRAINT "payroll_payments_amount" CHECK ("amount_minor" > 0);
ALTER TABLE "payroll_payments" ADD CONSTRAINT "payroll_payments_status" CHECK ("status" IN ('completed', 'failed', 'reversed'));
ALTER TABLE "payroll_payments" ADD CONSTRAINT "payroll_payments_method" CHECK ("method" IN ('bank_transfer', 'cash', 'cheque', 'external_provider', 'other'));
ALTER TABLE "payment_allocations" ADD CONSTRAINT "payment_allocations_amount" CHECK ("amount_minor" > 0);

-- Finalized payroll is immutable: once its period is locked, an item's figures can't change
-- (payments only move paid_minor). Shifts an approved payroll paid can't be edited either.
-- Corrections after that go into a later period as adjustments. A second guard behind the API's own checks.
CREATE FUNCTION "staff_payroll_item_frozen"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "payroll_periods" p WHERE p."id" = OLD."period_id" AND p."locked_at" IS NOT NULL)
     AND (NEW."gross_minor", NEW."other_earnings_minor", NEW."deductions_minor", NEW."net_minor", NEW."regular_seconds",
          NEW."overtime_seconds", NEW."double_time_seconds", NEW."holiday_seconds", NEW."lines", NEW."employee_id", NEW."period_id", NEW."currency")
         IS DISTINCT FROM
         (OLD."gross_minor", OLD."other_earnings_minor", OLD."deductions_minor", OLD."net_minor", OLD."regular_seconds",
          OLD."overtime_seconds", OLD."double_time_seconds", OLD."holiday_seconds", OLD."lines", OLD."employee_id", OLD."period_id", OLD."currency")
  THEN
    RAISE EXCEPTION 'payroll item % belongs to a finalized pay period', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "payroll_items_frozen" BEFORE UPDATE ON "payroll_items" FOR EACH ROW EXECUTE FUNCTION "staff_payroll_item_frozen"();

CREATE FUNCTION "staff_session_frozen"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF OLD."locked_at" IS NOT NULL AND NEW."locked_at" IS NOT NULL
     AND (NEW."clock_in_at", NEW."clock_out_at", NEW."employee_id", NEW."approval_status")
         IS DISTINCT FROM (OLD."clock_in_at", OLD."clock_out_at", OLD."employee_id", OLD."approval_status")
  THEN
    RAISE EXCEPTION 'shift % is part of a finalized payroll', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "attendance_sessions_frozen" BEFORE UPDATE ON "attendance_sessions" FOR EACH ROW EXECUTE FUNCTION "staff_session_frozen"();

CREATE FUNCTION "staff_break_frozen"() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM "attendance_sessions" s WHERE s."id" = NEW."session_id" AND s."locked_at" IS NOT NULL) THEN
    RAISE EXCEPTION 'shift % is part of a finalized payroll', NEW."session_id" USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "break_sessions_frozen" BEFORE INSERT OR UPDATE ON "break_sessions" FOR EACH ROW EXECUTE FUNCTION "staff_break_frozen"();

